mapper.select:
SELECT mp_alert.id, mp_alert.monitor_point_id, mp_alert.equipment_id, mp_alert.monitor_data, mp_alert.content, mp_alert.monitor_log, mp_alert.alert_type, mp_alert.monitor_alert_type, mp_alert.handle_time, mp_alert.recovery_data, mp_alert.recovery_time, mp_alert.handle_by, mp_alert.handle_state, mp_alert.handle_measures, mp_alert.handle_conclu, mp_alert.batch_id, mp_alert.create_time, mp_alert.update_time, eq_assets.asset_name, eq_assets.asset_code, loc.location_name, mp_point.point_name, mp_point.monitor_type, mp_point.monitor_son_type, mp_point.alarm_upper, mp_point.alarm_lower, mp_point.warn_upper, mp_point.warn_lower, mp_point.unit FROM monitor_point_alert mp_alert LEFT JOIN equipment_assets eq_assets ON mp_alert.equipment_id = eq_assets.asset_id LEFT JOIN equipment_monitor_point mp_point ON mp_alert.monitor_point_id = mp_point.id LEFT JOIN equipment_location loc ON eq_assets.location_id = loc.location_id
mp_alert.monitor_alert_type != '4'
AND mp_alert.alert_type = #{data.alertType}
AND mp_alert.monitor_alert_type = #{data.monitorAlertType}
AND mp_alert.equipment_id = #{data.assetId}
AND mp_alert.create_time >= #{data.startTime}
AND mp_alert.create_time <= #{data.endTime}
AND eq_assets.asset_name LIKE CONCAT('%', #{data.assetName}, '%')
AND mp_alert.handle_state = #{data.handleState}
ORDER BY mp_alert.create_time DESC
